// Cal.com on an API key: every operation of Cal.com's API v2 (actions.json, generated by
// `bun scripts/openapi-actions.ts calcom`), with bookings, meetings, recordings, forms and out-of-office starting
// automations by webhook (triggers.ts). A self-hosted Cal.com works too: its API address goes before the key.
import { isIP } from "node:net";
import { isPrivate } from "../../../link-title";
import { AppsError } from "../../types";
import type { OwnAction, OwnApp } from "../index";
import { type Api, call, specActions } from "../openapi";
import { events, receive, triggers, unwatch, wanted, watch } from "./triggers";

const CLOUD = "https://api.cal.com";
const HELP = "Cal.com → Settings → Developer → API keys";

// The key is "cal_live_..." alone, or "<API address> <key>" for a self-hosted Cal.com
export function parseKey(key: string): { base: string; token: string } {
  const parts = key.trim().split(/\s+/);
  if (parts.length === 1) return { base: CLOUD, token: parts[0]! };
  if (parts.length !== 2) throw new AppsError(`enter the API key, plus your Cal.com API address if it's self-hosted (${HELP})`);
  let u: URL;
  try {
    u = new URL(parts[0]!);
  } catch {
    throw new AppsError(`"${parts[0]}" isn't a web address. For a self-hosted Cal.com, start with its API address, like https://cal.example.com/api`);
  }
  // the key must never go out in the clear or to a machine on our own network
  // ponytail: checks the address as typed, not where its name resolves; a resolver check if anyone points a domain inward
  const host = u.hostname.replace(/^\[|\]$/g, "");
  if (u.protocol !== "https:") throw new AppsError("the Cal.com address must start with https://");
  if (host === "localhost" || host.endsWith(".local") || host.endsWith(".internal") || (isIP(host) && isPrivate(host))) throw new AppsError("that address isn't a public website");
  // the address may be given with or without its /v2: every call's path starts with /v2
  return { base: `${u.origin}${u.pathname.replace(/\/+$/, "").replace(/\/v2$/, "")}`, token: parts[1]! };
}

// each action's cal-api-version rides along in the input under this name, for auth() to send
const VERSION = "__cal_api_version";

export const api: Api = {
  name: "Cal.com",
  base: CLOUD,
  tokenHelp: HELP,
  auth: (key, input) => ({ Authorization: `Bearer ${parseKey(key).token}`, ...(input?.[VERSION] && { "cal-api-version": String(input[VERSION]) }) }),
  url: (key, _base, path) => `${parseKey(key).base}${path}`,
  // Cal.com says {"status": "error", "error": {...}}; almost always with an error status
  failed: (body) => (body?.status === "error" ? String(body.error?.message ?? body.error ?? "it didn't work") : undefined),
};

const ME = { method: "GET", path: "/v2/me", query: [], headers: [] };

const FILE = new URL("./actions.json", import.meta.url);
const { actions: generated } = (await Bun.file(FILE).json()) as { actions: { name: string; version?: string }[] };
const versions = new Map(generated.filter((a) => a.version).map((a) => [a.name, a.version!]));
const actions: Record<string, OwnAction> = await specActions(FILE, api);
for (const [name, version] of versions) {
  const a = actions[name]!;
  actions[name] = {
    description: a.description,
    readOnly: a.readOnly,
    // still built on first use
    get input() {
      return a.input;
    },
    run: (i: Record<string, unknown>, key: string) => a.run({ ...i, [VERSION]: version }, key),
  };
}

export const calcom: OwnApp = {
  app: "calcom",
  name: "Cal.com",
  logo: "/logos/calcom.svg",
  keyField: {
    label: "API key",
    help: "In Cal.com, open Settings → Developer → API keys, press Add, name it Emplio, choose Never expires, and copy the key (it starts with cal_live_). Emplio can then see and change whatever your Cal.com account can, including your team's and organization's if you're an admin. Self-hosted Cal.com: also enter your API address, like https://cal.example.com/api.",
    placeholder: "cal_live_...",
    sep: " ",
    parts: [{label:"API address (self-hosted only)",optional:true,placeholder:"https://cal.example.com/api"},{label:"API key",secret:true,placeholder:"cal_live_..."}],
  },
  async check(key) {
    const { data } = (await call(api, key, ME, {})) as { data: { name?: string; email?: string; username?: string; organization?: { name?: string } | null } };
    const who = data.name || data.email || data.username || "Cal.com";
    return data.organization?.name ? `${who} (${data.organization.name})` : who;
  },
  push: {
    events,
    triggers,
    start: (key, connection, event, config) => watch(api, key, connection, event, config),
    stop: (key, id) => unwatch(api, key, id),
    receive,
    wanted,
  },
  actions,
};
